diff --git a/solution.mjs b/solution.mjs
index 7c186e2..6b9af40 100644
--- a/solution.mjs
+++ b/solution.mjs
@@ -1,7 +1,10 @@
 export function intersection(a, b) {
+  const inB = new Set(b);
+  const seen = new Set();
   const result = [];
   for (const x of a) {
-    if (b.includes(x) && !result.includes(x)) {
+    if (inB.has(x) && !seen.has(x)) {
+      seen.add(x);
       result.push(x);
     }
   }
